package com.yjw.vultr;
import android.widget.*;
import java.util.*;
import java.math.BigDecimal;
import org.json.*;
final class CostsScreen {
 final MainActivity a;JSONObject account;ArrayList<MainActivity.Cost> rows;long checked;String error="";
 CostsScreen(MainActivity a){this.a=a;}
 void open(){restore();render();a.loadIfDue("costs",Refresher.COSTS,checked,this::fetch,this::updated);}
 void refresh(){a.load("costs",this::fetch,this::updated);if(a.tab.equals("费用"))render();}void load(){refresh();}
 void updated(){restore();if(a.tab.equals("费用"))a.renderLater("costs",()->checked+"|"+error+"|"+a.manager.data.opt("account_summary"),this::render);}
 // Bills are cached in the encrypted store so a restart does not re-read every invoice.
 void restore(){JSONObject cache=a.manager.data.optJSONObject("costs_cache");error=a.loadErrors.containsKey("costs")?"本次费用查询失败，保留上次记录；可点刷新重试":"";if(cache==null)return;try{ArrayList<MainActivity.Cost> list=new ArrayList<>();JSONArray all=cache.getJSONArray("rows");for(int i=0;i<all.length();i++){JSONObject r=all.getJSONObject(i);MainActivity.Cost c=new MainActivity.Cost();c.product=r.optString("product");c.description=r.optString("description");c.billed=Core.money(r.optString("billed","0"));c.pending=Core.money(r.optString("pending","0"));c.current=r.optBoolean("current");c.detail.append(r.optString("detail"));list.add(c);}rows=list;checked=cache.optLong("checked");account=new JSONObject().put("pending_charges",cache.optString("pending_charges","0"));}catch(Exception broken){rows=null;checked=0;}}
 void render(){int y=a.scroll().getScrollY();a.body.removeAllViews();AccountSummary.card(a,error,false);if(rows==null){LinearLayout c=a.card("完整费用明细",a.loading("costs")?"正在读取全部账单…":"包括历史服务器、自动备份及独立 IP。首次需读取全部账单。"+(error.isEmpty()?"":"\n"+error));if(a.loading("costs"))a.skeleton(c,14,90,70,85,55);else a.button(c,"查询完整账单",MainActivity.Tone.PRIMARY,()->load());a.restoreScroll(y);return;}
  BigDecimal billed=BigDecimal.ZERO,pending=BigDecimal.ZERO;for(MainActivity.Cost c:rows){billed=billed.add(c.billed);pending=pending.add(c.pending);}LinearLayout summary=a.card("历史费用摘要","美元 USD · "+Core.shortTime(checked)+" 更新"+(a.loading("costs")?" · 更新中…":"")+(error.isEmpty()?"":"\n"+error));a.fact(summary,"累计合计",Core.cash(billed.add(pending)));a.fact(summary,"已出账",Core.cash(billed));a.fact(summary,"未出账明细",Core.cash(pending));a.button(summary,"刷新全部账单",MainActivity.Tone.PLAIN,()->load());
  if(account!=null&&pending.compareTo(Core.money(account.optString("pending_charges")))!=0)a.card("汇总口径提示","明细与账户未出账汇总不一致，以最终账单为准。");
  a.body.addView(a.label("费用明细 · 在用未出账优先",18,a.INK));a.body.addView(a.label("当前实例中有未出账费用的服务器优先，其余按合计降序。左右滑动查看完整表格；点击行查看计费时间。",12,a.MUTED));HorizontalScrollView scroll=new HorizontalScrollView(a);a.body.addView(scroll);TableLayout table=new TableLayout(a);scroll.addView(table);a.tableRow(table,new String[]{"合计","已出账","未出账","状态 / 产品 / 账单描述"},false,true);if(rows.isEmpty())a.body.addView(a.label("账户当前没有费用明细。",14,a.MUTED));for(MainActivity.Cost row:rows){TableRow view=a.tableRow(table,new String[]{Core.cash(row.total()),Core.cash(row.billed),Core.cash(row.pending),(row.current?"● 当前实例  ":"")+row.product+" / "+row.description},row.current,false);view.setOnClickListener(v->a.message(row.product+" / "+row.description+"\n\n"+row.detail));}a.helpCard("统计口径","按账单产品和描述汇总；IP 重用可能合并多次部署。绿色与“当前实例”表示 IP、名称及计费时间匹配；其他行不等同于已确认删除。自动备份和独立 IP 分开列出。");a.restoreScroll(y);
 }
 void fetch()throws Exception{Api api=a.manager.api();JSONObject fetched=api.call("GET","/account",null).getJSONObject("account");AccountSummary.store(a.manager,fetched);JSONArray invoices=api.list("/billing/invoices","billing_invoices"),instances=api.list("/instances","instances");Map<String,MainActivity.Cost> groups=new HashMap<>();Set<String> seen=new HashSet<>();for(int i=0;i<invoices.length();i++){String id=invoices.getJSONObject(i).getString("id");if(!id.matches("[0-9]+"))throw new java.io.IOException("账单编号异常");if(seen.add(id))a.addCosts(groups,api.list("/billing/invoices/"+id+"/items","invoice_items"),false,instances);}a.addCosts(groups,api.list("/billing/pending-charges","pending_charges"),true,instances);ArrayList<MainActivity.Cost> sorted=new ArrayList<>(groups.values());sorted.sort((x,y)->{boolean xp=x.current&&x.pending.signum()>0,yp=y.current&&y.pending.signum()>0;if(xp!=yp)return xp?-1:1;return y.total().compareTo(x.total());});JSONArray out=new JSONArray();for(MainActivity.Cost c:sorted)out.put(new JSONObject().put("product",c.product).put("description",c.description).put("billed",c.billed.toPlainString()).put("pending",c.pending.toPlainString()).put("current",c.current).put("detail",c.detail.toString()));JSONObject cache=new JSONObject().put("checked",System.currentTimeMillis()).put("pending_charges",fetched.optString("pending_charges","0")).put("rows",out);a.manager.commit(()->a.manager.data.put("costs_cache",cache));}
}
